<template><input :id="id" :value="modelValue" :type="type" :name="name" :autocomplete="autocomplete" :placeholder="placeholder" :aria-invalid="Boolean(error)" :aria-describedby="describedBy" :disabled="disabled" class="min-h-11 w-full rounded-md border border-adm-line bg-adm-surface-2 px-3 py-2 text-adm-ink placeholder:text-adm-ink-muted focus:border-adm-focus focus:outline-none focus:ring-2 focus:ring-adm-focus/30 disabled:opacity-60" @input="$emit('update:modelValue', ($event.target as HTMLInputElement).value)"/></template>
<script setup lang="ts">import { computed } from 'vue';const props=withDefaults(defineProps<{id:string;modelValue?:string|number;type?:string;name?:string;autocomplete?:string;placeholder?:string;error?:string;hint?:string;disabled?:boolean}>(),{type:'text'});defineEmits<{ 'update:modelValue':[value:string] }>();const describedBy=computed(()=>[props.hint?props.id+'-hint':null,props.error?props.id+'-error':null].filter(Boolean).join(' ')||undefined)</script>
